function iconCatalog(){const out=[];names.forEach((n,i)=>{for(let v=0;v<22;v++){out.push({id:n+'-'+v,name:labels[n]||n,nameRu:iconRuLabels[n]||labels[n]||n,base:n,variant:v,svg:`<svg viewBox="0 0 24 24" aria-hidden="true"><g fill="none" stroke="currentColor" stroke-width="${1.6+(v%3)*.2}" stroke-linecap="round" stroke-linejoin="round">${paths[n]}</g>${v?`<circle cx="${18-(v%3)*2}" cy="${5+(v%4)*2}" r="${1.1+(v%2)*.35}" fill="var(--accent,#167347)" stroke="none"/>`:''}${v%5===1?'<path d="M2 2h20v20H2z" fill="none" stroke="currentColor" stroke-width=".65" opacity=".45"/>':''}</svg>`})}});return out}
const icons=iconCatalog();
function iconSvg(name){const it=icons.find(x=>x.base===name);return it?it.svg:(icons[0]?.svg||'')}
function typeUnit(type){const n=(type.fields||[]).length;return n<=1?'m.l.':n===2?'m²':'m³'}
function calcElement(e){const type=types.find(x=>x.id===e.typeId)||standardTypes[0],v=e.values||{},dims=(type.fields||[]).map(k=>Number(v[k])||0);let raw=dims.reduce((p,n)=>p*n,1);const count=Math.max(1,Number(e.count)||1);raw*=count;const rounded=Math.floor(raw)+(raw-Math.floor(raw)>=.4?1:0);return {raw,rounded,unit:typeUnit(type),type}}
function saveMeasures(){write('dp_measurements',measures);const tempIds=new Set(read('dp_measure_temp_types',[]).map(x=>x.id));write('dp_measure_types',types.filter(x=>!tempIds.has(x.id)))}
function renderMeasureRooms(){const host=$('dpMeasureRooms');if(!host)return;host.innerHTML=rooms.map((r,ri)=>{const els=(r.elements||[]),totals={};els.forEach(e=>{const c=calcElement(e),key=c.unit;totals[key]=(totals[key]||0)+(e.isDeduction?-c.raw:c.raw)});return `<div class="dp-measure-room"><div class="between"><input value="${esc(r.name)}" style="font-weight:750;max-width:65%" onchange="dpRoomRename(${ri},this.value)"><div class="row"><button class="secondary small" onclick="dpAddMeasureObject(${ri})">＋ Obiect</button><button class="danger small" onclick="dpDeleteRoom(${ri})">Șterge</button></div></div><div class="dp-measure-elements">${els.map((e,ei)=>{const c=calcElement(e),t=c.type;return `<div class="dp-measure-element"><div><label>Obiect / tip</label><div style="width:23px;height:23px;margin-bottom:4px">${iconSvg(e.icon||t.icon||'box')}</div><select onchange="dpChangeObjectType(${ri},${ei},this.value)">${types.map(x=>`<option value="${esc(x.id)}" ${x.id===e.typeId?'selected':''}>${esc(tr(x.name,x.ru||x.name))}</option>`).join('')}</select><div class="muted" style="font-size:10px;margin-top:3px">${esc(v41ElementName(e,c))}</div></div>${['length','width','height','depth'].map(k=>t.fields.includes(k)?`<div><label>${esc(fieldsMeta[k][window.lang==='ru'?1:0])} (m)</label><input type="number" min="0" step=".01" value="${Number(e.values?.[k])||0}" onchange="dpSetMeasureValue(${ri},${ei},'${k}',this.value)"></div>`:'').join('')}<div class="dp-measure-result">${c.raw.toFixed(2)} ${c.unit}<br><b>${c.rounded} ${c.unit}</b></div><button class="danger small" onclick="dpDeleteObject(${ri},${ei})">✕</button><div class="dp-measure-actions"><label class="dp-field-choice"><input type="checkbox" ${e.selected!==false?'checked':''} onchange="dpSelectMeasureObject(${ri},${ei},this.checked)"> Selectează pentru deviz</label>${t.deductible?`<label class="dp-field-choice"><input type="checkbox" ${e.isDeduction?'checked':''} onchange="dpToggleDeduction(${ri},${ei},this.checked)"> Scade din suprafață</label>`:''}<button class="secondary small" onclick="dpTransferOne(${ri},${ei})">Transferă în deviz</button><button class="secondary small" onclick="dpChooseObjectIcon(${ri},${ei})">Pictogramă</button></div></div>`}).join('')}</div><div class="dp-measure-summary">${Object.entries(totals).map(([u,v])=>`<span>${v.toFixed(2)} ${u}</span>`).join('')}<span>${els.length} obiecte</span></div><div class="dp-measure-actions"><button class="secondary small" onclick="dpTransferRoom(${ri})">Transferă încăperea în deviz</button></div></div>`}).join('')||'<div class="empty">Adaugă o încăpere pentru a începe.</div>'}
function renderSavedMeasures(){const el=$('dpMeasureSaved');if(!el)return;$('dpMeasureCount').textContent=measures.length;el.innerHTML=measures.slice().sort((a,b)=>new Date(b.updatedAt||0)-new Date(a.updatedAt||0)).map(m=>`<div class="dp-payment-card"><div class="between"><strong>${esc(m.name||m.address||'Releveu')}</strong><span class="meta">${new Date(m.updatedAt).toLocaleDateString()}</span></div><div class="meta">${esc(m.client||'')} · ${esc(m.address||'')} · ${(m.rooms||[]).length} încăperi · ${esc(m.zone||'')}</div><div class="row"><button class="secondary small" onclick="dpLoadMeasure('${m.id}')">Deschide</button><button class="danger small" onclick="dpDeleteMeasure('${m.id}')">Șterge</button></div></div>`).join('')||'<div class="empty">Nu există relevee salvate.</div>'}
window.dpMeasureNew=()=>{activeId=null;rooms=[];types=read('dp_measure_types',standardTypes);write('dp_measure_temp_types',[]);$('dpMeasureClient').value='';$('dpMeasureAddress').value='';$('dpMeasureZone').value='';$('dpMeasureName').value='';renderMeasureRooms()};
window.dpMeasureAddRoom=()=>{rooms.push({id:uid(),name:`${tr('Încăpere','Комната')} ${rooms.length+1}`,elements:[]});renderMeasureRooms()};
window.dpRoomRename=(i,v)=>{rooms[i].name=v};
window.dpDeleteRoom=i=>{if(confirm(tr('Ștergi încăperea și toate obiectele ei?','Удалить помещение и все его объекты?'))){rooms.splice(i,1);renderMeasureRooms()}};
window.dpAddMeasureObject=i=>{if(!types.length)return;rooms[i].elements.push({id:uid(),typeId:types[0].id,label:types[0].name,values:{length:0,width:0,height:0,depth:0},count:1,selected:true});renderMeasureRooms()};
window.dpChangeObjectType=(i,j,id)=>{const t=types.find(x=>x.id===id);if(!t)return;rooms[i].elements[j].typeId=id;rooms[i].elements[j].label=t.name;renderMeasureRooms()};
window.dpSetMeasureValue=(i,j,k,v)=>{rooms[i].elements[j].values[k]=Math.max(0,Number(v)||0);renderMeasureRooms()};
window.dpDeleteObject=(i,j)=>{rooms[i].elements.splice(j,1);renderMeasureRooms()};
window.dpSelectMeasureObject=(i,j,v)=>{rooms[i].elements[j].selected=v};
window.dpToggleDeduction=(i,j,v)=>{rooms[i].elements[j].isDeduction=v;renderMeasureRooms()};
window.dpChooseObjectIcon=(i,j)=>{selectedIconTarget={room:i,obj:j};dpOpenIconPicker()};
window.dpMeasureSave=()=>{const name=$('dpMeasureName').value.trim(),address=$('dpMeasureAddress').value.trim();if(!name&&!address){alert(tr('Introdu denumirea sau adresa obiectului.','Введите название или адрес объекта.'));return}const id=activeId||uid(),zone=$('dpMeasureZone').value.trim()||dpGuessZone(address);const obj={id,name,client:$('dpMeasureClient').value.trim(),address,zone,rooms:JSON.parse(JSON.stringify(rooms)),customTypes:read('dp_measure_temp_types',[]),updatedAt:new Date().toISOString()};const ix=measures.findIndex(x=>x.id===id);if(ix>=0)measures[ix]=obj;else measures.push(obj);activeId=id;saveMeasures();renderSavedMeasures();alert(tr('Măsurătoarea a fost salvată local.','Замер сохранён локально.'))};
window.dpLoadMeasure=id=>{const m=measures.find(x=>x.id===id);if(!m)return;activeId=id;rooms=JSON.parse(JSON.stringify(m.rooms||[]));const temp=m.customTypes||[];write('dp_measure_temp_types',temp);types=[...read('dp_measure_types',standardTypes),...temp.filter(x=>!read('dp_measure_types',standardTypes).some(y=>y.id===x.id))];$('dpMeasureClient').value=m.client||'';$('dpMeasureAddress').value=m.address||'';$('dpMeasureZone').value=m.zone||dpGuessZone(m.address);$('dpMeasureName').value=m.name||'';renderMeasureRooms()};
window.dpDeleteMeasure=id=>{if(!confirm(tr('Ștergi definitiv această măsurătoare?','Удалить этот замер безвозвратно?')))return;measures=measures.filter(x=>x.id!==id);saveMeasures();renderSavedMeasures()};
function transferElements(arr,roomName){if(typeof lines==='undefined')return alert('Deschide mai întâi Deviz Nou.');let count=0;arr.filter(e=>e.selected!==false).forEach(e=>{const c=calcElement(e),t=c.type,qty=Math.max(0,c.rounded);if(!qty)return;const label=`${roomName} – ${e.label||t.name}`;lines.push({id:uid(),code:'M-'+uid().slice(-6),ro:label,ru:label,unit:c.unit,price:0,defaultPrice:0,manualPrice:true,qty,discount:0,measurementSource:activeId||''});count++});if(count){if(typeof renderLinesAndPreview==='function')renderLinesAndPreview();if(typeof renderQuoteSearch==='function')renderQuoteSearch();showPage('quote');alert(`${count} obiect(e) transferate în Deviz Nou. Completează prețurile.`)}else alert('Selectează obiectele și introdu dimensiunile înainte de transfer.')};
window.dpTransferOne=(i,j)=>transferElements([rooms[i].elements[j]],rooms[i].name);
window.dpTransferRoom=i=>transferElements(rooms[i].elements,rooms[i].name);
window.dpMeasureTransferAll=()=>transferElements(rooms.flatMap(r=>r.elements.map(e=>({...e,_room:r.name}))), 'Măsurători');
function defaultTypeName(t){return tr(t.name,t.ru||t.name)}
