function renderTypeEditor(t){const host=$('dpMeasureTypeEditor');host.innerHTML=`<h3>${t.id?'Editează tipul':'Tip nou'}</h3><label>Denumire</label><input id="dpTypeName" value="${esc(t.name||'')}"><label style="margin-top:8px;display:block">Название (RU)</label><input id="dpTypeRu" value="${esc(t.ru||'')}"><div class="row" style="margin:10px 0"><button class="secondary" onclick="dpChooseTypeIcon()">Alege pictogramă</button><span id="dpTypeIconPreview">${iconSvg(t.icon||'box')}</span></div><strong>Câmpuri dimensionale</strong>${Object.entries(fieldsMeta).map(([k,v])=>`<label class="dp-field-choice"><input type="checkbox" id="dpField_${k}" ${(t.fields||[]).includes(k)?'checked':''}>${v[0]}</label>`).join('')}<label>Unitate rezultat</label><select id="dpTypeUnit"><option value="auto" ${!t.unit||t.unit==='auto'?'selected':''}>Automat după câmpuri</option><option value="m.l." ${t.unit==='m.l.'?'selected':''}>Metri liniari</option><option value="m²" ${t.unit==='m²'?'selected':''}>Metri pătrați</option><option value="m³" ${t.unit==='m³'?'selected':''}>Metri cubi</option><option value="buc." ${t.unit==='buc.'?'selected':''}>Bucăți</option></select><label class="dp-field-choice"><input id="dpTypeDeduct" type="checkbox" ${t.deductible?'checked':''}>Poate fi scăzut din suprafață</label><div class="row"><button onclick="dpSaveType()">Salvează în catalog</button><button class="secondary" onclick="dpAddTemporaryType()">OK – doar pentru releveul curent</button>${t.id?`<button class="danger small" onclick="dpDeleteType('${t.id}')">Șterge tipul</button>`:''}</div>`}
