function saveType(permanent){const name=$('dpTypeName').value.trim();if(!name)return alert(tr('Introdu denumirea tipului.','Введите название типа.'));const fields=Object.keys(fieldsMeta).filter(k=>$('dpField_'+k)?.checked);if(!fields.length)return alert(tr('Selectează cel puțin un câmp dimensional.','Выберите хотя бы одно поле размера.'));const t={id:editingType||uid(),name,ru:$('dpTypeRu').value.trim()||name,icon:editingTypeIcon||'box',fields,unit:$('dpTypeUnit').value,deductible:$('dpTypeDeduct').checked};editingTypeIcon='box';if(permanent){write('dp_measure_temp_types',read('dp_measure_temp_types',[]).filter(x=>x.id!==t.id));const i=types.findIndex(x=>x.id===t.id);if(i>=0)types[i]=t;else types.push(t);write('dp_measure_types',types);renderTypeSettings();renderMeasureRooms();alert(tr('Tip salvat în catalogul permanent.','Тип сохранён в постоянном каталоге.'))}else{const temp=read('dp_measure_temp_types',[]);temp.push(t);write('dp_measure_temp_types',temp);types.push(t);renderMeasureRooms();dpCloseMeasureSettings();alert(tr('Tip adăugat numai pentru măsurătoarea curentă. Salvează măsurătoarea pentru a-l păstra.','Тип добавлен только в текущий замер. Сохраните замер, чтобы сохранить тип.'))} }
window.dpDeleteType=id=>{const item=types.find(t=>t.id===id);if(!item)return;if(!confirm(`Ștergi tipul „${item.name}” din catalog? Măsurătorile deja salvate nu vor fi șterse.`))return;types=types.filter(t=>t.id!==id);write('dp_measure_types',types);write('dp_measure_temp_types',read('dp_measure_temp_types',[]).filter(t=>t.id!==id));renderTypeSettings();renderMeasureRooms()};
