window.dpRenderZones=()=>{const host=$('dpZoneList');if(!host)return;const q=($('dpZoneSearch').value||'').toLowerCase(),all=[...new Set([...zones,...read('dp_custom_zones',[])])];const cards=all.map(z=>{const qs=(typeof quotes!=='undefined'?quotes:[]).filter(x=>dpGuessZone(x.address)===z),ms=measures.filter(x=>(x.zone||dpGuessZone(x.address))===z);return {z,qs,ms}}).filter(x=>!q||x.z.toLowerCase().includes(q)||[...x.qs,...x.ms].some(o=>(o.address||'').toLowerCase().includes(q)||(o.client||'').toLowerCase().includes(q)));host.innerHTML=cards.map(x=>`<button class="dp-zone-card" onclick="dpShowZone('${esc(x.z)}')"><strong>${esc(x.z)}</strong><small>${x.qs.length} devize · ${x.ms.length} măsurători</small></button>`).join('')};
