const v41T=(ro,ru)=>tr(ro,ru);
const v41UnitLabel=u=>u==='m.l.'?'m.l.':u;
function v41Raw(e){const c=calcElement(e);return c.raw}
function v41ElementName(e,c){return e.label&&e.label!==c.type.name?e.label:v41T(c.type.name,c.type.ru||c.type.name)}
function v41ClipChildren(room,e){return (room.elements||[]).filter(x=>x.clippedTo===e.id)}
function v41Net(room,e){const c=calcElement(e),clips=v41ClipChildren(room,e);return c.raw-clips.reduce((a,x)=>a+v41Raw(x),0)}
