function v41PhotosUI(kind,ri,ei,arr){const key=kind==='room'?`room-${ri}`:`obj-${ri}-${ei}`;const count=(arr||[]).length;return `<div class="dp-v41-photos"><button type="button" class="secondary small dp-v41-photo-btn" onclick="dpV41PhotoPick('${kind}',${ri},${ei??-1},'camera')">📷 ${v41T('Cameră','Камера')}</button><button type="button" class="secondary small dp-v41-photo-btn" onclick="dpV41PhotoPick('${kind}',${ri},${ei??-1},'gallery')">▧ ${v41T('Galerie','Галерея')}</button><span class="dp-v41-photo-count">${count?`${count} ${v41T('fotografii','фото')}`:v41T('Fără fotografii','Нет фото')}</span>${(arr||[]).map((x,k)=>`<div class="dp-v49-photo-item"><button type="button" class="dp-v49-photo-view" aria-label="${v41T('Deschide fotografia','Открыть фото')} ${k+1}" onclick="dpV49PhotoView('${kind}',${ri},${ei??-1},${k})"><img class="dp-v41-thumb" src="${x}" alt="${v41T('Fotografie','Фото')} ${k+1}"></button><button type="button" class="dp-v49-photo-edit" aria-label="${v41T('Editează fotografia','Редактировать фото')} ${k+1}" onclick="dpV49PhotoEdit('${kind}',${ri},${ei??-1},${k})">✎</button></div>`).join('')}</div>`}
function v41ObjectHtml(r,ri,e,ei){const c=calcElement(e),t=c.type,clipped=!!e.clippedTo,parent=clipped?(r.elements||[]).find(x=>x.id===e.clippedTo):null,children=v41ClipChildren(r,e),net=v41Net(r,e),fields=['length','width','height','depth'];
 const dimHtml=fields.map(k=>t.fields.includes(k)?`<div><label>${esc(fieldsMeta[k][window.lang==='ru'?1:0])} (m)</label><input type="number" min="0" step=".01" value="${Number(e.values?.[k])||0}" onchange="dpSetMeasureValue(${ri},${ei},'${k}',this.value)" ${clipped?'disabled':''}></div>`:'').join('');
 if(clipped)return `<div class="dp-measure-element dp-v41-clipped" data-v41-item="object" data-ri="${ri}" data-ei="${ei}"><div class="linehead"><strong>↳ ${esc(v41ElementName(e,c))} <span class="pill">${v41T('MINUS','МИНУС')}</span></strong><strong style="color:var(--bad)">−${c.raw.toFixed(2)} ${c.unit}</strong></div><div class="linefields">${dimHtml}</div><div class="dp-measure-actions"><button class="secondary small" onclick="dpV41EditClip(${ri},${ei})">✎ ${v41T('Modifică dimensiuni','Изменить размеры')}</button><button class="secondary small" onclick="dpV41RestoreClip(${ri},${ei})">↩ ${v41T('Scoate din MINUS','Убрать из минуса')}</button></div></div>`;
 return `<div class="dp-measure-element" data-v41-item="object" data-ri="${ri}" data-ei="${ei}"><div class="dp-measure-element-grid"><div><div class="row"><button class="dp-v41-handle" type="button" data-v41-handle title="${v41T('Ține apăsat și trage','Удерживайте и перетащите')}">✥</button><label>${v41T('Obiect / tip','Объект / тип')}</label></div><button type="button" class="dp-v41-icon-button" aria-label="${v41T('Schimbă pictograma','Изменить значок')}" onclick="dpChooseObjectIcon(${ri},${ei})">${iconSvg(e.icon||t.icon||'box')}</button><select onchange="dpChangeObjectType(${ri},${ei},this.value)">${types.map(x=>`<option value="${esc(x.id)}" ${x.id===e.typeId?'selected':''}>${esc(tr(x.name,x.ru||x.name))}</option>`).join('')}</select><div class="muted" style="font-size:10px;margin-top:3px">${esc(v41ElementName(e,c))}</div></div>${dimHtml}<div class="dp-measure-result">${net.toFixed(2)} ${c.unit}<br><b>${Math.floor(net)+(net-Math.floor(net)>=.4?1:0)} ${c.unit}</b></div><div class="row"><button class="danger small" onclick="dpV41StartClip(${ri},${ei})">− ${v41T('Minus','Минус')}</button><button class="secondary small" onclick="dpDeleteObject(${ri},${ei})">✕</button></div></div><div class="dp-measure-actions"><label class="dp-field-choice"><input type="checkbox" ${e.selected!==false?'checked':''} onchange="dpSelectMeasureObject(${ri},${ei},this.checked)"> ${v41T('Selectează pentru deviz','Выбрать для сметы')}</label><label class="dp-field-choice"><input type="checkbox" ${e.mergeSelected?'checked':''} onchange="dpV41MergeCheck(${ri},${ei},this.checked)"> ${v41T('Selectează pentru MERGE','Выбрать для MERGE')}</label><button class="secondary small" onclick="dpV41EditClip(${ri},${ei})">✎</button></div>${children.length?`<div class="dp-v41-clips">${children.map(x=>v41ObjectHtml(r,ri,x,r.elements.indexOf(x))).join('')}</div>`:''}${v41PhotosUI('object',ri,ei,e.photos||[])}</div>`}
renderMeasureRooms=function(){const host=$('dpMeasureRooms');if(!host)return;host.innerHTML=rooms.map((r,ri)=>{r.merges=r.merges||[];const all=r.elements||[],clipped=all.filter(e=>e.clippedTo),roots=all.filter(e=>!e.clippedTo),groups=r.merges.filter(g=>(g.componentIds||[]).some(id=>roots.some(e=>e.id===id)));const groupedIds=new Set(groups.flatMap(g=>g.componentIds||[]));const totals={};roots.forEach(e=>{const u=calcElement(e).unit;totals[u]=(totals[u]||0)+v41Net(r,e)});const summaryHtml=`<div class="dp-measure-summary">${Object.entries(totals).map(([u,v])=>`<span>${v.toFixed(2)} ${u}</span>`).join('')}<span>${all.length} ${v41T('obiecte','объектов')}</span></div>`;const groupHtml=groups.map(g=>{const allMembers=(g.componentIds||[]).map(id=>r.elements.find(e=>e.id===id)).filter(Boolean);const members=allMembers.filter(e=>!e.clipTo);const total=members.reduce((sum,e)=>sum+v41Net(r,e),0),unit=members[0]?calcElement(members[0]).unit:'';return `<div class="dp-v41-merge" data-v41-item="merge" data-ri="${ri}" data-gid="${esc(g.id)}"><div class="dp-v41-merge-title"><button class="dp-v41-handle" type="button" data-v41-merge-handle title="${v41T('Ține apăsat și trage pentru reordonare','Удерживайте и перетащите для сортировки')}">✥</button><span>▦ ${esc(g.name||v41T('Grup','Группа'))} (${allMembers.length})</span><strong>${total.toFixed(2)} ${unit}</strong></div><div class="dp-v41-merge-components">${members.map(e=>v41ObjectHtml(r,ri,e,r.elements.indexOf(e))).join('')}</div><div class="dp-measure-actions"><button class="secondary small" onclick="dpV41RenameMerge(${ri},'${esc(g.id)}')">✎ ${v41T('Redenumește','Переименовать')}</button><button class="secondary small" onclick="dpV41Ungroup(${ri},'${esc(g.id)}')">${v41T('Desface grupul','Разъединить группу')}</button></div></div>`}).join('');const otherHtml=roots.filter(e=>!groupedIds.has(e.id)).map(e=>v41ObjectHtml(r,ri,e,all.indexOf(e))).join('');const clippedUnattached=clipped.filter(e=>!all.some(p=>p.id===e.clippedTo));return `<div class="dp-measure-room" data-v41-item="room" data-ri="${ri}"><div class="between"><div class="row" style="flex:1"><button class="dp-v41-handle" type="button" data-v41-handle title="${v41T('Ține apăsat și trage pentru mutare','Удерживайте и перетащите для перемещения')}">✥</button><input value="${esc(r.name)}" style="font-weight:750;max-width:65%" onchange="dpRoomRename(${ri},this.value)"></div><div class="row"><button class="secondary small" onclick="dpAddMeasureObject(${ri})">＋ ${v41T('Obiect','Объект')}</button><button class="danger small" onclick="dpDeleteRoom(${ri})">${v41T('Șterge','Удалить')}</button></div></div>${v41PhotosUI('room',ri,-1,r.photos||[])}${groupHtml}${otherHtml}${clippedUnattached.map(e=>v41ObjectHtml(r,ri,e,all.indexOf(e))).join('')}${summaryHtml}<div class="dp-measure-actions"><button class="secondary small" onclick="dpV41MergeSelected(${ri})">⊕ MERGE ${v41T('obiecte selectate','выбранные объекты')}</button></div></div>`}).join('')||`<div class="empty">${v41T('Adaugă o încăpere pentru a începe.','Добавьте помещение, чтобы начать.')}</div>`;v41BindMeasureDrag()};
window.dpSetMeasureValue=(ri,ei,k,v)=>{const r=rooms[ri],e=r?.elements?.[ei];if(!e||e.clippedTo)return;const old=e.values?.[k]||0;e.values=e.values||{};e.values[k]=Math.max(0,Number(v)||0);const deducted=v41ClipChildren(r,e).reduce((a,x)=>a+calcElement(x).raw,0);if(calcElement(e).raw+0.000001<deducted){e.values[k]=old;alert(v41T('Dimensiunea nu poate fi redusă sub suma obiectelor deduse prin MINUS.','Размер нельзя уменьшить ниже суммы объектов, вычтенных через МИНУС.'));renderMeasureRooms();return}saveMeasures();renderMeasureRooms()};
window.dpDeleteObject=(ri,ei)=>{const r=rooms[ri],e=r?.elements?.[ei];if(!e)return;const children=v41ClipChildren(r,e);if(children.length&&!confirm(v41T(`Obiectul are ${children.length} elemente scăzute. La ștergere, acestea vor reveni independente în încăpere. Continui?`,`У объекта есть ${children.length} вычтенных элементов. При удалении они вернутся в помещение как независимые. Продолжить?`)))return;children.forEach(x=>delete x.clippedTo);r.merges=(r.merges||[]).map(g=>({...g,componentIds:(g.componentIds||[]).filter(id=>id!==e.id)})).filter(g=>g.componentIds.length>=2);r.elements.splice(ei,1);saveMeasures();renderMeasureRooms()};
const dpV41OldChangeType=window.dpChangeObjectType;window.dpChangeObjectType=(ri,ei,id)=>{const r=rooms[ri],e=r?.elements?.[ei],next=types.find(x=>x.id===id);if(!e||!next)return;const newUnit=typeUnit(next),children=v41ClipChildren(r,e);if(children.some(x=>calcElement(x).unit!==newUnit)){alert(v41T('Tipul nou are altă unitate decât obiectele scăzute. Scoate obiectele din MINUS înainte de schimbare.','Новый тип имеет другую единицу измерения. Сначала уберите объекты из минуса.'));return}const g=(r.merges||[]).find(g=>(g.componentIds||[]).includes(e.id));if(g&&(g.componentIds||[]).some(cid=>cid!==e.id&&r.elements.some(x=>x.id===cid&&!x.clippedTo&&calcElement(x).unit!==newUnit))){alert(v41T('Tipul nou nu corespunde unității grupului MERGE. Desfă grupul sau alege un tip compatibil.','Новый тип не соответствует единице группы MERGE. Разъедините группу или выберите совместимый тип.'));return}dpV41OldChangeType(ri,ei,id);saveMeasures()};
window.dpV41MergeCheck=(ri,ei,v)=>{rooms[ri].elements[ei].mergeSelected=v};
window.dpV41MergeSelected=ri=>{const r=rooms[ri],picked=(r.elements||[]).filter(e=>e.mergeSelected&&!e.clippedTo);if(picked.length<2)return alert(v41T('Selectează cel puțin două obiecte compatibile.','Выберите не менее двух совместимых объектов.'));const units=new Set(picked.map(e=>calcElement(e).unit));if(units.size!==1)return alert(v41T('Obiectele selectate au unități diferite și nu pot fi unite.','Выбранные объекты имеют разные единицы измерения и не могут быть объединены.'));const firstType=calcElement(picked[0]).type,wallType=firstType.id==='wall'||/perete|стен/i.test(firstType.name||'');const defaultGroupName=wallType?v41T('Pereți','Стены'):v41T(firstType.name,firstType.ru||firstType.name);const name=prompt(v41T('Denumirea grupului MERGE:','Название группы MERGE:'),defaultGroupName);if(!name)return;r.merges=r.merges||[];const ids=picked.map(e=>e.id);r.merges=r.merges.filter(g=>!g.componentIds?.some(id=>ids.includes(id)));r.merges.push({id:uid(),name:name.trim(),componentIds:ids});picked.forEach(e=>e.mergeSelected=false);saveMeasures();renderMeasureRooms()};
window.dpV41RenameMerge=(ri,id)=>{const g=rooms[ri].merges?.find(x=>x.id===id);if(!g)return;const n=prompt(v41T('Denumirea grupului:','Название группы:'),g.name);if(n){g.name=n.trim();saveMeasures();renderMeasureRooms()}};
window.dpV41Ungroup=(ri,id)=>{const r=rooms[ri];r.merges=(r.merges||[]).filter(g=>g.id!==id);saveMeasures();renderMeasureRooms()};
window.dpV41StartClip=(ri,parentIndex)=>{const r=rooms[ri],parent=r.elements[parentIndex],pc=calcElement(parent),options=(r.elements||[]).filter((e,i)=>i!==parentIndex&&!e.clippedTo&&calcElement(e).unit===pc.unit);if(!options.length)return alert(v41T('Nu există obiecte cu aceeași unitate de măsură în această încăpere.','В этом помещении нет объектов с такой же единицей измерения.'));const html=`<div class="dp-v41-photo-modal" id="dpV41ClipModal"><div><div class="between"><h3>${v41T('Alege obiectul de scăzut','Выберите вычитаемый объект')}</h3><button class="secondary small" onclick="document.getElementById('dpV41ClipModal').remove()">✕</button></div><p class="muted">${v41T('Alege obiectul. Unitatea va fi verificată înainte de deducere.','Выберите объект. Единица измерения будет проверена перед вычитанием.')}</p><div class="dp-v41-ruler-list">${options.map(e=>{const c=calcElement(e),idx=r.elements.indexOf(e);return `<button class="dp-v41-ruler-item" onclick="dpV41ApplyClip(${ri},'${parent.id}','${e.id}')"><span>${esc(v41ElementName(e,c))}</span><strong>${c.raw.toFixed(2)} ${c.unit}</strong></button>`}).join('')}</div></div></div>`;document.body.insertAdjacentHTML('beforeend',html)};
window.dpV41ApplyClip=(ri,parentId,childId)=>{const r=rooms[ri],parent=r.elements.find(x=>x.id===parentId),child=r.elements.find(x=>x.id===childId);if(!parent||!child)return;const pu=calcElement(parent).unit,cu=calcElement(child).unit;if(pu!==cu){alert(v41T('Unitatea de măsură nu corespunde și obiectul nu poate fi dedus din obiectul/tipul selectat.','Единица измерения не совпадает, объект нельзя вычесть из выбранного объекта/типа.'));return}const remaining=v41Net(r,parent);if(calcElement(child).raw>remaining+0.000001){alert(v41T('Deducerea depășește dimensiunea rămasă a obiectului principal.','Вычитаемая величина превышает оставшийся размер основного объекта.'));return}child.clippedTo=parent.id;parent.clipIds=[...new Set([...(parent.clipIds||[]),child.id])];saveMeasures();document.getElementById('dpV41ClipModal')?.remove();renderMeasureRooms()};
window.dpV41RestoreClip=(ri,ei)=>{const e=rooms[ri].elements[ei],p=rooms[ri].elements.find(x=>x.id===e.clippedTo);if(p)p.clipIds=(p.clipIds||[]).filter(id=>id!==e.id);delete e.clippedTo;saveMeasures();renderMeasureRooms()};
window.dpV41EditClip=(ri,ei)=>{const e=rooms[ri].elements[ei],t=calcElement(e).type,fields=t.fields||[],vals=fields.map(k=>`${fieldsMeta[k][window.lang==='ru'?1:0]}: ${e.values?.[k]||0}`).join('\n');const input=prompt(v41T('Modifică dimensiunile (valoare pentru fiecare câmp, în ordinea afișată):\n','Измените размеры (значения полей в указанном порядке):\n')+vals,fields.map(k=>e.values?.[k]||0).join(';'));if(input===null)return;const nums=input.split(/[;,\s]+/).map(Number);if(nums.length!==fields.length||nums.some(x=>!Number.isFinite(x)||x<0))return alert(v41T('Dimensiuni invalide.','Некорректные размеры.'));const oldValues={...(e.values||{})};fields.forEach((k,i)=>e.values[k]=nums[i]);const parent=rooms[ri].elements.find(x=>x.id===e.clippedTo),others=rooms[ri].elements.filter(x=>x.clippedTo===e.clippedTo&&x.id!==e.id).reduce((a,x)=>a+calcElement(x).raw,0);if(parent&&calcElement(parent).raw-others-calcElement(e).raw<-.000001){e.values=oldValues;alert(v41T('Dimensiunea introdusă depășește suprafața disponibilă pentru deducere.','Введённый размер превышает доступную величину для вычитания.'));return}saveMeasures();renderMeasureRooms()};
window.dpV41PhotoPick=(kind,ri,ei,source)=>{const inp=document.createElement('input');inp.type='file';inp.accept='image/*';inp.multiple=true;if(source==='camera')inp.setAttribute('capture','environment');inp.onchange=async()=>{const target=kind==='room'?rooms[ri]:rooms[ri]?.elements?.[ei];if(!target)return;target.photos=target.photos||[];const previousPhotoCount=target.photos.length;for(const file of [...inp.files||[]]){try{const data=await new Promise((resolve,reject)=>{const fr=new FileReader();fr.onload=()=>resolve(fr.result);fr.onerror=reject;fr.readAsDataURL(file)});const img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=reject;img.src=data});const canvas=document.createElement('canvas'),scale=Math.min(1,1280/Math.max(img.width,img.height));canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);target.photos.push(canvas.toDataURL('image/jpeg',.72))}catch(err){console.warn('Photo import failed',err)}}try{saveMeasures()}catch(err){target.photos.length=previousPhotoCount;alert(v41T('Nu s-au putut salva fotografiile. Exportă un backup sau selectează mai puține imagini.','Не удалось сохранить фотографии. Создайте резервную копию или выберите меньше изображений.'));return}renderMeasureRooms()};inp.click()};
function v41BindMeasureDrag(){const host=$('dpMeasureRooms');if(!host||host.dataset.v41Drag==='1')return;host.dataset.v41Drag='1';let timer=null,drag=null,start=null;host.addEventListener('pointerdown',e=>{const h=e.target.closest('[data-v41-handle],[data-v41-merge-handle]');if(!h)return;const item=h.closest('[data-v41-item="room"], [data-v41-item="object"], [data-v41-item="merge"]');if(!item||item.classList.contains('dp-v41-clipped'))return;start={x:e.clientX,y:e.clientY};timer=setTimeout(()=>{const type=item.dataset.v41Item,ri=Number(item.dataset.ri),ei=Number(item.dataset.ei),obj=type==='object'?rooms[ri].elements[ei]:null,merge=obj?(rooms[ri].merges||[]).find(g=>(g.componentIds||[]).includes(obj.id)):null;drag={item,type,ri,ei,gid:item.dataset.gid,objectGroupId:merge?.id||''};item.classList.add('dp-v41-dragging');try{h.setPointerCapture(e.pointerId)}catch{}},520)});host.addEventListener('pointermove',e=>{if(!drag&&timer&&start&&Math.hypot(e.clientX-start.x,e.clientY-start.y)>12){clearTimeout(timer);timer=null}if(drag){const selector=drag.type==='room'?'[data-v41-item="room"]':drag.type==='object'?'[data-v41-item="object"]:not(.dp-v41-clipped)':'[data-v41-item="merge"]';const target=document.elementFromPoint(e.clientX,e.clientY)?.closest(selector);host.querySelectorAll('.dp-v41-drop-target').forEach(x=>x.classList.remove('dp-v41-drop-target'));if(target&&target!==drag.item&&(drag.type==='room'||Number(target.dataset.ri)===drag.ri)){if(drag.type==='object'){const dest=rooms[drag.ri].elements[Number(target.dataset.ei)],destGroup=(rooms[drag.ri].merges||[]).find(g=>(g.componentIds||[]).includes(dest?.id));if((destGroup?.id||'')!==(drag.objectGroupId||''))return}target.classList.add('dp-v41-drop-target')}}});const finish=()=>{clearTimeout(timer);timer=null;if(drag){const target=host.querySelector('.dp-v41-drop-target');if(target){if(drag.type==='room'){const to=Number(target.dataset.ri),[moved]=rooms.splice(drag.ri,1);rooms.splice(to,0,moved)}else if(drag.type==='object'){const r=rooms[drag.ri],from=drag.ei,to=Number(target.dataset.ei);if(from!==to){const [moved]=r.elements.splice(from,1);r.elements.splice(to,0,moved);(r.merges||[]).forEach(g=>{g.componentIds=(g.componentIds||[]).filter(id=>r.elements.some(x=>x.id===id)).sort((a,b)=>r.elements.findIndex(x=>x.id===a)-r.elements.findIndex(x=>x.id===b))})}}else{const r=rooms[drag.ri],from=(r.merges||[]).findIndex(g=>g.id===drag.gid),to=(r.merges||[]).findIndex(g=>g.id===target.dataset.gid);if(from>=0&&to>=0&&from!==to){const [moved]=r.merges.splice(from,1);r.merges.splice(to,0,moved)}}saveMeasures()}drag.item.classList.remove('dp-v41-dragging');host.querySelectorAll('.dp-v41-drop-target').forEach(x=>x.classList.remove('dp-v41-drop-target'));drag=null;renderMeasureRooms()}start=null};host.addEventListener('pointerup',finish);host.addEventListener('pointercancel',finish)}
// Selectorul de măsurători în Deviz nou; datele originale rămân nemodificate.
window.dpRefreshQuoteMeasurements=()=>{const sel=$('dpQuoteMeasurement');if(!sel)return;const saved=read('dp_measurements',[]).slice().sort((a,b)=>new Date(b.updatedAt||0)-new Date(a.updatedAt||0)),current=window.__dpSelectedMeasureId||localStorage.getItem('dp_quote_measure_id')||'';sel.innerHTML=`<option value="">${v41T('Nici-o măsurătoare','Без замера')}</option>`+saved.map(m=>`<option value="${esc(m.id)}">${esc(m.name||m.address||v41T('Măsurătoare','Замер'))} · ${new Date(m.updatedAt||Date.now()).toLocaleDateString()}</option>`).join('');sel.value=saved.some(m=>m.id===current)?current:'';window.__dpSelectedMeasureId=sel.value;localStorage.setItem('dp_quote_measure_id',sel.value)};
window.dpSelectQuoteMeasurement=id=>{window.__dpSelectedMeasureId=id||'';localStorage.setItem('dp_quote_measure_id',id||'')};
window.dpStartQuoteFromMeasure=()=>{try{const name=$('dpMeasureName').value.trim(),address=$('dpMeasureAddress').value.trim();if(!name&&!address){alert(v41T('Introdu denumirea măsurătorii și salveaz-o înainte de a crea devizul.','Перед созданием сметы укажите название замера и сохраните его.'));return}dpMeasureSave();const chosen=activeId||'';if(lines.length&&!confirm(v41T('Începi un deviz nou? Devizul aflat acum în lucru trebuie salvat înainte.','Начать новую смету? Текущую смету нужно сохранить заранее.')))return;resetQuoteForm();window.__dpSelectedMeasureId=chosen;localStorage.setItem('dp_quote_measure_id',chosen);if(typeof showPage==='function')showPage('quote');dpRefreshQuoteMeasurements()}catch(e){console.error(e);alert(v41T('Nu s-a putut deschide Deviz nou. Salvează măsurătoarea și încearcă din nou.','Не удалось открыть новую смету. Сохраните замер и повторите попытку.'))}};
function v41CalcForMeasure(e,m){const all=[...types,...(m.customTypes||[]),...read('dp_measure_types',standardTypes)],type=all.find(x=>x.id===e.typeId)||standardTypes[0],dims=(type.fields||[]).map(k=>Number(e.values?.[k])||0),raw=dims.reduce((a,b)=>a*b,1)*Math.max(1,Number(e.count)||1);return {raw,unit:typeUnit(type),type}}function v41NetForMeasure(r,e,m){const c=v41CalcForMeasure(e,m);return c.raw-(r.elements||[]).filter(x=>x.clippedTo===e.id).reduce((a,x)=>a+v41CalcForMeasure(x,m).raw,0)}
window.dpV41OpenRuler=lineIndex=>{const id=window.__dpSelectedMeasureId||localStorage.getItem('dp_quote_measure_id')||'';const m=read('dp_measurements',[]).find(x=>x.id===id);if(!m)return alert(v41T('Selectează mai întâi o măsurătoare.','Сначала выберите замер.'));const rows=[];(m.rooms||[]).forEach(r=>{const es=r.elements||[],clips=es.filter(e=>e.clippedTo);const groups=(r.merges||[]).map(g=>{const allMembers=(g.componentIds||[]).map(cid=>es.find(e=>e.id===cid)).filter(Boolean),members=allMembers.filter(e=>!e.clippedTo);if(!members.length)return null;const unit=v41CalcForMeasure(members[0],m).unit,total=members.reduce((sum,e)=>sum+v41NetForMeasure(r,e,m),0);return {name:`${g.name} (${allMembers.length})`,qty:total,unit,room:r.name,components:members}}).filter(Boolean);const grouped=new Set(groups.flatMap(g=>g.components.map(e=>e.id)));rows.push({room:r.name,groups,items:es.filter(e=>!e.clippedTo&&!grouped.has(e.id)).map(e=>({name:e.label||v41CalcForMeasure(e,m).type.name,qty:v41NetForMeasure(r,e,m),unit:v41CalcForMeasure(e,m).unit,room:r.name,id:e.id}))})});let html=`<div class="dp-v41-photo-modal" id="dpV41RulerModal"><div><div class="between"><h3>${v41T('Alege dimensiunea','Выберите размер')}</h3><button class="secondary small" onclick="document.getElementById('dpV41RulerModal').remove()">✕</button></div><div class="dp-v41-ruler-list">`;rows.forEach(r=>{html+=`<div class="dp-v41-ruler-group"><strong>${esc(r.room)}</strong>`;r.groups.forEach(g=>{html+=`<button class="dp-v41-ruler-item" onclick="dpV41ApplyRuler(${lineIndex},${g.qty},'${g.unit}','${esc(r.room+' – '+g.name)}')"><span>▦ ${esc(g.name)}</span><strong>${g.qty.toFixed(2)} ${g.unit}</strong></button>`;g.components.forEach(e=>{const c=v41CalcForMeasure(e,m);html+=`<button class="dp-v41-ruler-item" style="padding-left:22px!important" onclick="dpV41ApplyRuler(${lineIndex},${v41NetForMeasure(r,e,m)},'${c.unit}','${esc(r.room+' – '+(e.label||c.type.name))}')"><span>↳ ${esc(v41ElementName(e,c))}</span><strong>${v41NetForMeasure(r,e,m).toFixed(2)} ${c.unit}</strong></button>`})});r.items.forEach(e=>{html+=`<button class="dp-v41-ruler-item" onclick="dpV41ApplyRuler(${lineIndex},${e.qty},'${e.unit}','${esc(r.room+' – '+e.name)}')"><span>${esc(e.name)}</span><strong>${e.qty.toFixed(2)} ${e.unit}</strong></button>`}) ;html+='</div>'});html+='</div></div></div>';document.body.insertAdjacentHTML('beforeend',html)};
window.dpV41ApplyRuler=(i,qty,unit,label)=>{if(typeof lines==='undefined'||!lines[i])return;const current=String(lines[i].unit||'').toLowerCase().replace(/\s/g,'');const expected=String(unit||'').toLowerCase().replace(/\s/g,'');const normUnit=x=>{const z=x.split('/')[0].trim();return z.includes('m³')||z.includes('m3')?'m³':z.includes('m²')||z.includes('m2')?'m²':z.includes('m.l')||z==='ml'?'m.l.':z}; if(current&&normUnit(current)!==normUnit(expected)){alert(v41T('Unitatea de măsură nu corespunde lucrării selectate.','Единица измерения не соответствует выбранной работе.'));return}updateLine(i,'qty',qty);if(label)lines[i].measurementLabel=label;renderLinesAndPreview();document.getElementById('dpV41RulerModal')?.remove()};
