// Administrare zone: redenumire, sortare, ștergere sigură și transfer multiplu de devize.
function v41ZoneNames(){const custom=read('dp_custom_zones',[]),extra=(typeof quotes!=='undefined'?quotes:[]).map(q=>q.zone).filter(Boolean),fromMeasures=measures.map(m=>m.zone).filter(Boolean),aliases=read('dp_zone_aliases',{}),deleted=read('dp_zone_deleted',[]);return [...new Set([...zones,...custom,...extra,...fromMeasures].map(z=>aliases[z]||z))].filter(z=>z&&!deleted.includes(z))}
function v41ZoneOf(o){const aliases=read('dp_zone_aliases',{});const base=o.zone||dpGuessZone(o.address||'');return aliases[base]||base}
window.dpRenderZones=()=>{const host=$('dpZoneList');if(!host)return;const q=($('dpZoneSearch')?.value||'').toLowerCase(),qs=typeof quotes!=='undefined'?quotes:[],all=v41ZoneNames().map(z=>{const zq=qs.filter(x=>v41ZoneOf(x)===z),ms=measures.filter(x=>v41ZoneOf(x)===z);return {z,qs:zq,ms}});const sort=$('dpZoneSort')?.value||'manual';if(sort==='az')all.sort((a,b)=>a.z.localeCompare(b.z,window.lang==='ru'?'ru':'ro'));if(sort==='count-desc')all.sort((a,b)=>b.qs.length-a.qs.length||a.z.localeCompare(b.z));if(sort==='count-asc')all.sort((a,b)=>a.qs.length-b.qs.length||a.z.localeCompare(b.z));if(sort==='manual'){const order=read('dp_zone_order',[]);all.sort((a,b)=>{const ai=order.indexOf(a.z),bi=order.indexOf(b.z);return (ai<0?9999:ai)-(bi<0?9999:bi)})}const filtered=all.filter(x=>!q||x.z.toLowerCase().includes(q)||[...x.qs,...x.ms].some(o=>(o.address||'').toLowerCase().includes(q)||(o.client||'').toLowerCase().includes(q)));host.innerHTML=filtered.map(x=>`<div class="dp-zone-card" data-v41-zone="${esc(x.z)}" style="display:flex;align-items:center;gap:8px"><button class="dp-v41-handle" type="button" data-v41-zone-handle title="${v41T('Ține apăsat și trage pentru reordonare','Удерживайте и перетащите для сортировки')}">✥</button><button class="secondary small" onclick="dpShowZone('${esc(x.z)}')" style="flex:1;text-align:left;background:transparent;color:var(--text)"><strong>${esc(x.z)}</strong><small>${x.qs.length} ${v41T('devize','смет')} · ${x.ms.length} ${v41T('măsurători','замеров')}</small></button><button class="secondary small" onclick="dpRenameZone('${esc(x.z)}')" title="${v41T('Redenumește','Переименовать')}">✎</button><button class="danger small" onclick="dpDeleteZoneSafe('${esc(x.z)}')" title="${v41T('Șterge zona','Удалить район')}">✕</button></div>`).join('')||`<div class="empty">${v41T('Nu există zone.','Нет районов.')}</div>`;v41BindZoneDrag()};
function v41BindZoneDrag(){const host=$('dpZoneList');if(!host||host.dataset.v41ZoneDrag==='1')return;host.dataset.v41ZoneDrag='1';let timer=null,drag=null,start=null;host.addEventListener('pointerdown',e=>{if(!e.target.closest('[data-v41-zone-handle]'))return;const row=e.target.closest('[data-v41-zone]');if(!row)return;start={x:e.clientX,y:e.clientY};timer=setTimeout(()=>{drag={row,zone:row.dataset.v41Zone};row.classList.add('dp-v41-dragging')},1200)});host.addEventListener('pointermove',e=>{if(!drag&&timer&&start&&Math.hypot(e.clientX-start.x,e.clientY-start.y)>12){clearTimeout(timer);timer=null}if(drag){const row=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-v41-zone]');host.querySelectorAll('.dp-v41-drop-target').forEach(x=>x.classList.remove('dp-v41-drop-target'));if(row&&row!==drag.row)row.classList.add('dp-v41-drop-target')}});const end=()=>{clearTimeout(timer);timer=null;if(drag){const target=host.querySelector('.dp-v41-drop-target');if(target){const names=v41ZoneNames(),from=names.indexOf(drag.zone),to=names.indexOf(target.dataset.v41Zone);if(from>=0&&to>=0){names.splice(from,1);names.splice(to,0,drag.zone);write('dp_zone_order',names);if($('dpZoneSort'))$('dpZoneSort').value='manual'}}drag.row.classList.remove('dp-v41-dragging');host.querySelectorAll('.dp-v41-drop-target').forEach(x=>x.classList.remove('dp-v41-drop-target'));drag=null;dpRenderZones()}start=null};host.addEventListener('pointerup',end);host.addEventListener('pointercancel',end)}
window.dpRenameZone=old=>{const n=prompt(v41T('Noul nume al zonei:','Новое название района:'),old);if(!n||!n.trim()||n.trim()===old)return;const name=n.trim(),aliases=read('dp_zone_aliases',{});aliases[old]=name;write('dp_zone_aliases',aliases);const a=read('dp_custom_zones',[]).filter(x=>x!==old);if(!zones.includes(name)&&!a.includes(name))a.push(name);write('dp_custom_zones',a);write('dp_zone_deleted',read('dp_zone_deleted',[]).filter(x=>x!==name));if(typeof quotes!=='undefined')quotes.forEach(q=>{if(v41ZoneOf(q)===old)q.zone=name});measures.forEach(m=>{if(v41ZoneOf(m)===old)m.zone=name});if(typeof persist==='function')persist();saveMeasures();dpRenderZones();$('dpZoneDetails').innerHTML=''};
window.dpDeleteZoneSafe=z=>{const all=v41ZoneNames().filter(x=>x!==z);if(!all.length)return alert(v41T('Nu există altă zonă pentru transfer. Creează mai întâi o zonă nouă.','Нет другого района для переноса. Сначала создайте новый район.'));const target=prompt(v41T('Zona care va primi devizele și măsurătorile existente:\n','Район, в который будут перенесены существующие сметы и замеры:\n')+all.join('\n'),all[0]);if(!target||!all.includes(target))return;if(!confirm(v41T(`Confirmi ștergerea zonei „${z}” și transferul conținutului în „${target}”? Niciun deviz nu va fi șters.`,`Подтвердите удаление района «${z}» и перенос содержимого в «${target}»? Ни одна смета не будет удалена.`)))return;if(typeof quotes!=='undefined')quotes.forEach(q=>{if(v41ZoneOf(q)===z)q.zone=target});measures.forEach(m=>{if(v41ZoneOf(m)===z)m.zone=target});write('dp_custom_zones',read('dp_custom_zones',[]).filter(x=>x!==z));write('dp_zone_deleted',[...new Set([...read('dp_zone_deleted',[]),z])]);const aliases=read('dp_zone_aliases',{});Object.keys(aliases).forEach(k=>{if(aliases[k]===z)delete aliases[k]});write('dp_zone_aliases',aliases);if(typeof persist==='function')persist();saveMeasures();dpRenderZones();$('dpZoneDetails').innerHTML=''};
window.dpShowZone=z=>{const qs=(typeof quotes!=='undefined'?quotes:[]).filter(x=>v41ZoneOf(x)===z),ms=measures.filter(x=>v41ZoneOf(x)===z),all=v41ZoneNames().filter(x=>x!==z);$('dpZoneDetails').innerHTML=`<div class="card dp-zone-details"><div class="between"><h3>${esc(z)}</h3><button class="secondary small" onclick="dpRenameZone('${esc(z)}')">✎ ${v41T('Redenumește','Переименовать')}</button></div><div class="fields"><div class="field"><label>${v41T('Transferă devizele selectate în zona','Перенести выбранные сметы в район')}</label><select id="dpZoneTransferTarget"><option value="">${v41T('Alege zona','Выберите район')}</option>${all.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('')}</select></div><div class="field" style="align-self:end"><button onclick="dpTransferSelectedZoneQuotes('${esc(z)}')">${v41T('Transferă selectate','Перенести выбранные')}</button></div></div><h4>${v41T('Devize','Сметы')} (${qs.length})</h4>${qs.map(q=>`<div class="dp-type-row" style="display:flex;align-items:center;gap:8px"><input type="checkbox" class="dp-zone-quote-check" value="${esc(q.id)}"><strong style="flex:1">${esc(q.name||q.client||v41T('Deviz fără nume','Смета без названия'))}</strong><span>${esc(q.address||'')}</span><span>${esc(q.date||'')}</span><button class="secondary small" onclick="loadQuote('${q.id}')">✎</button></div>`).join('')||`<div class="muted">${v41T('Nu există devize în această zonă.','В этом районе нет смет.')}</div>`}<h4>${v41T('Măsurători','Замеры')} (${ms.length})</h4>${ms.map(m=>`<div class="dp-type-row"><strong>${esc(m.name||m.address)}</strong><span>${esc(m.client||'')}</span><button class="secondary small" onclick="showPage('measurements');dpLoadMeasure('${m.id}')">${v41T('Deschide','Открыть')}</button></div>`).join('')||`<div class="muted">${v41T('Nu există măsurători în această zonă.','В этом районе нет замеров.')}</div>`}</div>`};
window.dpTransferSelectedZoneQuotes=z=>{const target=$('dpZoneTransferTarget')?.value;if(!target)return alert(v41T('Alege zona de destinație.','Выберите район назначения.'));const ids=[...document.querySelectorAll('.dp-zone-quote-check:checked')].map(x=>x.value);if(!ids.length)return alert(v41T('Selectează cel puțin un deviz.','Выберите хотя бы одну смету.'));quotes.forEach(q=>{if(ids.includes(q.id))q.zone=target});persist();dpRenderZones();dpShowZone(z);alert(v41T('Devizele selectate au fost transferate.','Выбранные сметы перенесены.'))};


window.dpV41BindQuoteDrag=()=>{const host=$('quoteLines');if(!host||host.dataset.v41PressDrag==='1')return;host.dataset.v41PressDrag='1';let timer=null,drag=null,start=null;host.addEventListener('pointerdown',e=>{const h=e.target.closest('[data-v41-quote-handle]');if(!h)return;const row=h.closest('[data-line-index]');if(!row)return;start={x:e.clientX,y:e.clientY};timer=setTimeout(()=>{drag={from:Number(row.dataset.lineIndex),row};row.classList.add('dp-v41-dragging')},1300)});host.addEventListener('pointermove',e=>{if(!drag&&timer&&start&&Math.hypot(e.clientX-start.x,e.clientY-start.y)>12){clearTimeout(timer);timer=null}if(drag){const row=document.elementFromPoint(e.clientX,e.clientY)?.closest('#quoteLines [data-line-index]');host.querySelectorAll('.dp-v41-drop-target').forEach(x=>x.classList.remove('dp-v41-drop-target'));if(row&&row!==drag.row)row.classList.add('dp-v41-drop-target')}});const end=()=>{clearTimeout(timer);timer=null;if(drag){const target=host.querySelector('.dp-v41-drop-target');if(target){let from=drag.from,to=Number(target.dataset.lineIndex);while(from!==to){const step=to>from?1:-1;moveLine(from,step);from+=step;if(step<0)to--}}drag.row.classList.remove('dp-v41-dragging');host.querySelectorAll('.dp-v41-drop-target').forEach(x=>x.classList.remove('dp-v41-drop-target'));drag=null}start=null};host.addEventListener('pointerup',end);host.addEventListener('pointercancel',end)};


// Press & Drag pentru grupe, subgrupe și devize din interiorul grupelor.
window.dpV41BindGroupDrag=()=>{const host=$('quoteGroups');if(!host)return;host.querySelectorAll('.group-move').forEach(box=>{const b=box.querySelector('button[onclick*="moveGroup"]');if(!b)return;const m=(b.getAttribute('onclick')||'').match(/moveGroup\('([^']+)'/);if(!m)return;const card=box.closest('.quote-card');if(!card)return;card.dataset.v41GroupId=m[1];if(!box.querySelector('[data-v41-group-handle]')){const h=document.createElement('button');h.type='button';h.className='dp-v41-handle';h.textContent='✥';h.title=v41T('Ține apăsat și trage pentru reordonare','Удерживайте и перетащите для сортировки');h.setAttribute('data-v41-group-handle','');box.insertBefore(h,box.firstChild)}box.querySelectorAll('button[onclick*="moveGroup"]').forEach(x=>x.style.display='none')});host.querySelectorAll('.work').forEach(row=>{const b=row.querySelector('button[onclick*="moveQuoteInGroup"]');if(!b)return;const m=(b.getAttribute('onclick')||'').match(/moveQuoteInGroup\('([^']+)',-?1,'([^']+)'\)/);if(!m)return;row.dataset.v41QuoteId=m[1];row.dataset.v41Gid=m[2];const controls=b.parentElement;if(!controls.querySelector('[data-v41-group-quote-handle]')){const h=document.createElement('button');h.type='button';h.className='dp-v41-handle';h.textContent='✥';h.title=v41T('Ține apăsat și trage pentru reordonare','Удерживайте и перетащите для сортировки');h.setAttribute('data-v41-group-quote-handle','');controls.insertBefore(h,controls.firstChild)}controls.querySelectorAll('button[onclick*="moveQuoteInGroup"]').forEach(x=>x.style.display='none')});if(host.dataset.v41GroupDrag==='1')return;host.dataset.v41GroupDrag='1';let timer=null,drag=null,start=null;host.addEventListener('pointerdown',e=>{const gh=e.target.closest('[data-v41-group-handle]'),qh=e.target.closest('[data-v41-group-quote-handle]');if(!gh&&!qh)return;const row=gh?gh.closest('[data-v41-group-id]'):qh.closest('[data-v41-quote-id]');if(!row)return;start={x:e.clientX,y:e.clientY};timer=setTimeout(()=>{drag={row,type:gh?'group':'quote',id:gh?row.dataset.v41GroupId:row.dataset.v41QuoteId,gid:row.dataset.v41Gid};row.classList.add('dp-v41-dragging')},1200)});host.addEventListener('pointermove',e=>{if(!drag&&timer&&start&&Math.hypot(e.clientX-start.x,e.clientY-start.y)>12){clearTimeout(timer);timer=null}if(drag){const selector=drag.type==='group'?'[data-v41-group-id]':'[data-v41-quote-id]';const target=document.elementFromPoint(e.clientX,e.clientY)?.closest(selector);host.querySelectorAll('.dp-v41-drop-target').forEach(x=>x.classList.remove('dp-v41-drop-target'));if(target&&target!==drag.row&&(drag.type!=='quote'||target.dataset.v41Gid===drag.gid))target.classList.add('dp-v41-drop-target')}});const finish=()=>{clearTimeout(timer);timer=null;if(drag){const target=host.querySelector('.dp-v41-drop-target');if(target){if(drag.type==='group'){const item=quoteGroups.find(x=>x.id===drag.id),to=quoteGroups.find(x=>x.id===target.dataset.v41GroupId);if(item&&to&&(item.parentId||'')===(to.parentId||'')){let siblings=quoteGroups.filter(x=>(x.parentId||'')===(item.parentId||'')).sort((a,b)=>(Number(a.order)||0)-(Number(b.order)||0));let from=siblings.findIndex(x=>x.id===item.id),dest=siblings.findIndex(x=>x.id===to.id);while(from!==dest){moveGroup(item.id,dest>from?1:-1);siblings=quoteGroups.filter(x=>(x.parentId||'')===(item.parentId||'')).sort((a,b)=>(Number(a.order)||0)-(Number(b.order)||0));from=siblings.findIndex(x=>x.id===item.id);dest=siblings.findIndex(x=>x.id===to.id)}}}else{let arr=quotes.filter(q=>q.groupId===drag.gid).sort((a,b)=>(Number(a.groupOrder)||0)-(Number(b.groupOrder)||0));let from=arr.findIndex(q=>q.id===drag.id),dest=arr.findIndex(q=>q.id===target.dataset.v41QuoteId);while(from!==dest&&from>=0&&dest>=0){moveQuoteInGroup(drag.id,dest>from?1:-1,drag.gid);arr=quotes.filter(q=>q.groupId===drag.gid).sort((a,b)=>(Number(a.groupOrder)||0)-(Number(b.groupOrder)||0));from=arr.findIndex(q=>q.id===drag.id);dest=arr.findIndex(q=>q.id===target.dataset.v41QuoteId)}}}drag.row.classList.remove('dp-v41-dragging');host.querySelectorAll('.dp-v41-drop-target').forEach(x=>x.classList.remove('dp-v41-drop-target'));drag=null;window.dpV41BindGroupDrag()}start=null};host.addEventListener('pointerup',finish);host.addEventListener('pointercancel',finish)};
