/* V42: initialize enhancement renderers after the original V40 init() has completed. */
window.dpV42Boot=function(){try{
  if(typeof renderMeasureRooms==='function')renderMeasureRooms();
  if(typeof renderSavedMeasures==='function')renderSavedMeasures();
  if(typeof dpRefreshQuoteMeasurements==='function')dpRefreshQuoteMeasurements();
  if(typeof dpRenderZones==='function')dpRenderZones();
  if(typeof renderLinesAndPreview==='function')renderLinesAndPreview();
  if(typeof renderQuoteGroups==='function')renderQuoteGroups();
  document.documentElement.dataset.devizproBuild='V42';
  console.info('DevizPRO V42 enhancement layer initialized');
}catch(err){console.error('DevizPRO V42 initialization error',err)}};
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(window.dpV42Boot,0),{once:true});else setTimeout(window.dpV42Boot,0);
